        running: Running {
            work: c.running.work.clone(),
            bookmark: c.running.bookmark.clone(),
            dry_run: c.running.dry_run,
        },
        agent: c.agent.clone(),
        title: Some(rung),
        body: c.body.clone(),
        push: c.push,
        same_version: c.same_version,
    };
