//! The `rung` subcommand: a rung's acts, each a subcommand of its own.
//!
//! - `next` starts the next rung, the first not done, marking it
//!   `(current)` in the working copy's `zTOC.md`, and with `--ver`
//!   sets the version by the config's `[version] bump`.
//! - `stop` clears the marker, the edits in `@` left as they are.
//! - `commit` commits the current rung, by `cycle --commit`'s own
//!   code, its title the rung's, the ladder it carries marking it
//!   `(done)` and none current.
//!
//! The marker lives in the working copy alone: a commit ends its rung
//! and starts none, so no commit's tree claims work not yet begun.

use std::path::{Path, PathBuf};

use clap::{Args, Subcommand};
use log::info;

use super::{
    CommitRung, Running, branch_titles, commit_rung, commit_scope, cycle_bookmark, record,
    resolve_repos,
};
use crate::context::Context;
use crate::options_flags::dry_run::DryRunFlag;
use crate::options_flags::scope::{RepoScope, repo_scope_parser};
use crate::subcommand::SubcommandRunner;

/// Run a rung's acts.
#[derive(Args, Debug)]
pub struct RungArgs {
    #[command(subcommand)]
    pub command: RungCommand,
}

/// The `rung` subcommands.
#[derive(Subcommand, Debug)]
pub enum RungCommand {
    /// Start the next rung: mark the first rung not done `(current)` in zTOC.md
    #[command(
        long_about = "Start the next rung: mark the first rung not done `(current)`\n\
        in the working copy's zTOC.md, refused while a rung is current.\n\
        With --ver, set the version first, by the command the config's\n\
        `[version] bump` names, `{ver}` the version given, so the dev\n\
        build under review carries it. No commit is made."
    )]
    Next(NextArgs),

    /// Leave the current rung: clear its `(current)` marker, the edits left alone
    Stop(Where),

    /// Commit the current rung: its title the rung's, the ladder marking it `(done)`
    #[command(
        long_about = "Commit the working copies as the current rung, as `cycle\n\
        --commit` does, its title the rung's: the ladder is rewritten into\n\
        the commit, the rung `(done)` and none current, so the next rung\n\
        starts by `rung next`. The opening's body defaults, and a work rung\n\
        gives --body. The closing is `cycle --close`'s. Refused with no\n\
        rung current."
    )]
    Commit(CommitArgs),
}

/// Where, and the cycle's bookmark when it is not the title's slug.
#[derive(Args, Debug)]
pub struct Where {
    /// The cycle's bookmark, in place of the title's slug
    #[arg(long, value_name = "NAME")]
    pub bookmark: Option<String>,

    /// Where: a path in the workspace, its root or either repo, or a
    /// plain repo [default: the current directory]
    #[arg(short = 'R', long, value_name = "PATH")]
    pub repo: Option<PathBuf>,

    /// Say what would be done, and do none of it
    #[command(flatten)]
    pub dry_run: DryRunFlag,
}

/// `rung next`'s arguments.
#[derive(Args, Debug)]
pub struct NextArgs {
    /// The rung's version, set by the config's `[version] bump` before
    /// the rung is marked [default: the version left as it is]
    #[arg(long, value_name = "VERSION")]
    pub ver: Option<String>,

    #[command(flatten)]
    pub at: Where,
}

/// `rung commit`'s arguments.
#[derive(Args, Debug)]
pub struct CommitArgs {
    /// Which repos, required: `b|both` a dual workspace's pair,
    /// `w|work` the work half with the agent half left to push, and
    /// `p|por` a plain repo
    #[arg(
        short = 's',
        long,
        value_name = "SCOPE",
        value_parser = repo_scope_parser(&["work", "both", "por"]),
        help = "Which repos, required: `w|work`, `b|both`, or `p|por`"
    )]
    pub scope: RepoScope,

    /// The commit's body, the problem and its solution, or @PATH to
    /// read it from a file [default: `[opening] body` for the opening]
    #[arg(long, value_name = "STR|@PATH")]
    pub body: Option<String>,

    /// Publish the cycle's bookmark once committed, a draft push
    #[arg(long)]
    pub push: bool,

    /// Commit although the version's line is unchanged
    #[arg(long)]
    pub same_version: bool,

    #[command(flatten)]
    pub at: Where,
}

/// Inputs to the rung op, clap-free.
#[derive(Debug)]
pub enum RungParams {
    Next {
        running: Running,
        ver: Option<String>,
    },
    Stop(Running),
    Commit(CommitRung),
}

impl Where {
    fn running(&self) -> Result<(Running, Option<PathBuf>), String> {
        let (work, agent) = resolve_repos(self.repo.as_deref())?;
        Ok((
            Running {
                work,
                bookmark: self.bookmark.clone(),
                dry_run: self.dry_run.value,
            },
            agent,
        ))
    }
}

impl TryFrom<&RungArgs> for RungParams {
    type Error = String;

    fn try_from(a: &RungArgs) -> Result<Self, String> {
        match &a.command {
            RungCommand::Next(n) => Ok(RungParams::Next {
                running: n.at.running()?.0,
                ver: match n.ver.as_deref().map(str::trim) {
                    Some("") => return Err("rung next: --ver is blank".into()),
                    v => v.map(String::from),
                },
            }),
            RungCommand::Stop(w) => Ok(RungParams::Stop(w.running()?.0)),
            RungCommand::Commit(c) => {
                let (running, agent) = c.at.running()?;
                let body = match &c.body {
                    Some(b) => Some(crate::desc_helpers::read_body(b, "rung commit")?),
                    None => None,
                };
                if body.as_deref().is_some_and(|b| b.trim().is_empty()) {
                    return Err("rung commit: a --body given is not blank".into());
                }
                Ok(RungParams::Commit(CommitRung {
                    agent: commit_scope(Some(&c.scope), agent, "rung commit")?,
                    running,
                    title: None,
                    body,
                    push: c.push,
                    same_version: c.same_version,
                }))
            }
        }
    }
}

impl SubcommandRunner for RungArgs {
    type Params = RungParams;

    fn to_params(&self) -> Result<Self::Params, String> {
        RungParams::try_from(self)
    }

    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        match params {
            RungParams::Next { running, ver } => next(running, ver.as_deref()),
            RungParams::Stop(r) => stop(r),
            RungParams::Commit(c) => commit(ctx, c),
        }
    }
}

/// The cycle's state as a rung's act needs it: its title, its rung

//! The `rung` subcommand: a rung's acts, each a subcommand of its own.
//!
//! - `next` starts the next rung, the first not done, marking it
//!   `(current)` in the working copy's `zTOC.md`, and with `--ver`
//!   sets the version by the config's `[version] bump`.
//! - `stop` clears the marker, the edits in `@` left as they are.
//! - `commit` commits the current rung, by `cycle --commit`'s own
//!   code, its title the rung's, the ladder it carries marking it
//!   `(done)` and none current.
//!
//! The marker lives in the working copy alone: a commit ends its rung
//! and starts none, so no commit's tree claims work not yet begun.

use std::path::{Path, PathBuf};

use clap::{Args, Subcommand};
use log::info;

use super::{
    CommitRung, Running, branch_titles, commit_rung, commit_scope, cycle_bookmark, record,
    resolve_repos,
};
use crate::context::Context;
use crate::options_flags::dry_run::DryRunFlag;
use crate::options_flags::scope::{RepoScope, repo_scope_parser};
use crate::subcommand::SubcommandRunner;

/// Run a rung's acts.
#[derive(Args, Debug)]
pub struct RungArgs {
    #[command(subcommand)]
    pub command: RungCommand,
}

/// The `rung` subcommands.
#[derive(Subcommand, Debug)]
pub enum RungCommand {
    /// Start the next rung: mark the first rung not done `(current)` in zTOC.md
    #[command(
        long_about = "Start the next rung: mark the first rung not done `(current)`\n\
        in the working copy's zTOC.md, refused while a rung is current.\n\
        With --ver, set the version first, by the command the config's\n\
        `[version] bump` names, `{ver}` the version given, so the dev\n\
        build under review carries it. No commit is made."
    )]
    Next(NextArgs),

    /// Leave the current rung: clear its `(current)` marker, the edits left alone
    Stop(Where),

    /// Commit the current rung: its title the rung's, the ladder marking it `(done)`
    #[command(
        long_about = "Commit the working copies as the current rung, as `cycle\n\
        --commit` does, its title the rung's: the ladder is rewritten into\n\
        the commit, the rung `(done)` and none current, so the next rung\n\
        starts by `rung next`. The opening's body defaults, and a work rung\n\
        gives --body. The closing is `cycle --close`'s. Refused with no\n\
        rung current."
    )]
    Commit(CommitArgs),
}

/// Where, and the cycle's bookmark when it is not the title's slug.
#[derive(Args, Debug)]
pub struct Where {
    /// The cycle's bookmark, in place of the title's slug
    #[arg(long, value_name = "NAME")]
    pub bookmark: Option<String>,

    /// Where: a path in the workspace, its root or either repo, or a
    /// plain repo [default: the current directory]
    #[arg(short = 'R', long, value_name = "PATH")]
    pub repo: Option<PathBuf>,

    /// Say what would be done, and do none of it
    #[command(flatten)]
    pub dry_run: DryRunFlag,
}

/// `rung next`'s arguments.
#[derive(Args, Debug)]
pub struct NextArgs {
    /// The rung's version, set by the config's `[version] bump` before
    /// the rung is marked [default: the version left as it is]
    #[arg(long, value_name = "VERSION")]
    pub ver: Option<String>,

    #[command(flatten)]
    pub at: Where,
}

/// `rung commit`'s arguments.
#[derive(Args, Debug)]
pub struct CommitArgs {
    /// Which repos, required: `b|both` a dual workspace's pair,
    /// `w|work` the work half with the agent half left to push, and
    /// `p|por` a plain repo
    #[arg(
        short = 's',
        long,
        value_name = "SCOPE",
        value_parser = repo_scope_parser(&["work", "both", "por"]),
        help = "Which repos, required: `w|work`, `b|both`, or `p|por`"
    )]
    pub scope: RepoScope,

    /// The commit's body, the problem and its solution, or @PATH to
    /// read it from a file [default: `[opening] body` for the opening]
    #[arg(long, value_name = "STR|@PATH")]
    pub body: Option<String>,

    /// Publish the cycle's bookmark once committed, a draft push
    #[arg(long)]
    pub push: bool,

    /// Commit although the version's line is unchanged
    #[arg(long)]
    pub same_version: bool,

    #[command(flatten)]
    pub at: Where,
}

/// Inputs to the rung op, clap-free.
#[derive(Debug)]
pub enum RungParams {
    Next {
        running: Running,
        ver: Option<String>,
    },
    Stop(Running),
    Commit(CommitRung),
}

impl Where {
    fn running(&self) -> Result<(Running, Option<PathBuf>), String> {
        let (work, agent) = resolve_repos(self.repo.as_deref())?;
        Ok((
            Running {
                work,
                bookmark: self.bookmark.clone(),
                dry_run: self.dry_run.value,
            },
            agent,
        ))
    }
}

impl TryFrom<&RungArgs> for RungParams {
    type Error = String;

    fn try_from(a: &RungArgs) -> Result<Self, String> {
        match &a.command {
            RungCommand::Next(n) => Ok(RungParams::Next {
                running: n.at.running()?.0,
                ver: match n.ver.as_deref().map(str::trim) {
                    Some("") => return Err("rung next: --ver is blank".into()),
                    v => v.map(String::from),
                },
            }),
            RungCommand::Stop(w) => Ok(RungParams::Stop(w.running()?.0)),
            RungCommand::Commit(c) => {
                let (running, agent) = c.at.running()?;
                let body = match &c.body {
                    Some(b) => Some(crate::desc_helpers::read_body(b, "rung commit")?),
                    None => None,
                };
                if body.as_deref().is_some_and(|b| b.trim().is_empty()) {
                    return Err("rung commit: a --body given is not blank".into());
                }
                Ok(RungParams::Commit(CommitRung {
                    agent: commit_scope(Some(&c.scope), agent, "rung commit")?,
                    running,
                    title: None,
                    body,
                    push: c.push,
                    same_version: c.same_version,
                }))
            }
        }
    }
}

impl SubcommandRunner for RungArgs {
    type Params = RungParams;

    fn to_params(&self) -> Result<Self::Params, String> {
        RungParams::try_from(self)
    }

    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        match params {
            RungParams::Next { running, ver } => next(running, ver.as_deref()),
            RungParams::Stop(r) => stop(r),
            RungParams::Commit(c) => commit(ctx, c),
        }
    }
}

