    pub multi_step: bool,

    /// Land the closing on TARGET in the same invocation, as `cycle
    /// land` does
    #[arg(long, value_name = "TARGET", help_heading = "Land")]
    pub land: Option<String>,

    /// With `--land`, which side of the cycle's bookmark is kept:
