    #[command(flatten)]
    pub scope: Scope,

    /// Join a target that moved by a merge commit, the target its first
    /// parent and the cycle's last commit its second, made and then
    /// landed, a tree no rung validated [default: a target that moved is
    /// refused]
    #[arg(long)]
