    pub bookmark: Option<String>,
    pub dry_run: bool,
}

/// A rung's commit's inputs, `rung commit`'s and `cycle close`'s: the
/// cycle, the repos the commit is made in, and the title and body
/// given.
#[derive(Debug)]
pub struct CommitRung {
