    fn open_makes_the_bookmark_alone() {
        let fx = Fixture::new("cycle-open-alone");
        let err = run(&fx.work, &["--open", "--title", "feat: a cycle"]).unwrap_err();
        assert!(
            err.contains("no TODO.md or zTOC.md") && err.contains("--no-record"),
