content.content:
    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        match params {
            RungParams::Next { running, ver } => next(running, ver.as_deref()),
            RungParams::Stop(r) => stop(r),
            RungParams::Commit(c) => commit(ctx, c),
        }
    }
